-- +goose Up
-- The whole app schema in one migration: the migration history collapsed (ADR 0047,
-- History-Collapse), diffed from the ent schema. What ent's diff cannot express (the storage
-- parameters and the schema_state row at the end) is added by hand, and three partial indexes keep
-- the predicates the ent schema writes, which Postgres stores in the form ent's diff reads back;
-- river's tables are their own migrations.
-- create "api_tokens" table
CREATE TABLE "api_tokens" ("id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY, "created_at" timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP, "updated_at" timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP, "name" character varying NOT NULL, "prefix" character varying NOT NULL, "secret_hash" character varying NOT NULL, "scopes" jsonb NOT NULL, "expires_at" timestamptz NULL, "revoked_at" timestamptz NULL, "last_used_at" timestamptz NULL, "membership_id" bigint NULL, "oauth_client_id" bigint NULL, "workspace_id" bigint NOT NULL, PRIMARY KEY ("id"), CONSTRAINT "api_tokens_oauth_client_check" CHECK ((oauth_client_id IS NULL) OR (membership_id IS NOT NULL)));
-- create index "api_tokens_prefix_key" to table: "api_tokens"
CREATE UNIQUE INDEX "api_tokens_prefix_key" ON "api_tokens" ("prefix");
-- create index "apitoken_oauth_client_id" to table: "api_tokens"
CREATE INDEX "apitoken_oauth_client_id" ON "api_tokens" ("oauth_client_id");
-- create index "apitoken_workspace_id_membership_id" to table: "api_tokens"
CREATE INDEX "apitoken_workspace_id_membership_id" ON "api_tokens" ("workspace_id", "membership_id");
